function.arguments:
{
  "database": "video_game_store",
  "collection": "Purchase History",
  "pipeline": [
    {
      "$match": {
        "Transaction Date": {
          "$gte": { "$date": "2018-01-01" },
          "$lte": { "$date": "2018-12-31" }
        },
        "Customer Segment": "First-time",
        "Product Category": { "$in": ["PC Games", "Console Games"] }
      }
    },
    {
      "$group": {
        "_id": null,
        "totalNewClients": { "$sum": 1 },
        "totalSales": { "$sum": "$Purchase Amount ($)" }
      }
    }
  ]
}
